insert into programs (id, client_id, name, type, level, weeks, week_notes) values ('37eb776e-25e4-5ec6-a069-4c70e0afd608', 'a5d556f4-215e-5f89-8c70-c31e7b9eb6c4', 'BG · 3-Day Week (Tue/Thu + Metabolic)', 'Functional', 'Intermediate', 4, '{"1": "BG''s week: Tue + Thu from the whiteboard, plus a Metabolic Day as day 3. Tue/Thu rule: complete all sets of a lettered section, then its core, then move on. Thursday uses the SAME core pair after every section. The xN beside each section = sets of the superset/compound set.", "4": "Reassess: nudge loads up where the last week felt controlled; swap treadmill intervals for bike (or vice versa) on the metabolic day for variety."}'::jsonb) on conflict (id) do nothing;
